typedef void (*EventFn)(int event_data);

void logger(int d) { /* Log the event */ }
void notifier(int d) { /* Send notification */ }

// 1. Registration variable (The callback slot)
EventFn event_dispatcher = logger;

// 2. Registration function
void SetHandler(EventFn handler) {
    event_dispatcher = handler;
}

// 3. Invocation point (The runtime call)
void RaiseEvent(int data) {
    event_dispatcher(data);
}

// Usage:
// SetHandler(notifier);
// RaiseEvent(99); // Executes notifier(99)
// SetHandler(logger);
// RaiseEvent(10); // Executes logger(10)
